import networkx as nx
from itertools import combinations

def is_valid(G):
    if G.number_of_nodes() != 16:
        return False
    if G.number_of_edges() < 19 or G.number_of_edges() > 21:
        return False
    if min(dict(G.degree()).values()) < 1:
        return False
    if max(dict(G.degree()).values()) > 3:
        return False
    if nx.graph_clique_number(G) > 2:
        return False
    if nx.graph_independence_number(G) > 5:
        return False
    if nx.chromatic_number(G) < 2 or nx.chromatic_number(G) > 3:
        return False
    if nx.node_connectivity(G) < 1:
        return False
    if nx.girth(G) < 4:
        return False
    return True

