# Let's try a random bipartite graph.

import random

def find_graph():
    for _ in range(100000):
        G = nx.Graph()
        G.add_nodes_from(range(16))
        edges = set()
        while len(edges) < 20:
            u = random.randint(0, 7)
            v = random.randint(8, 15)
            edges.add((u, v))
        G.add_edges_from(edges)

        if is_valid(G):
            return list(G.edges())
    return None

print(find_graph())
